fn main() {
    // Create a value and wrap it in a Box
    let boxed_value = Box::new(42);

    // Assert the Box holds the value by dereferencing
    assert_eq!(*boxed_value, 42);

    // Define a function that expects an owned Box
    fn consume_box(boxed: Box<i32>) {
        // Assert the function receives the wrapped value
        assert_eq!(*boxed, 42);
    }

    // Move the Box into the function
    consume_box(boxed_value);

    println!("Ownership transfer verified successfully");
}
